<script>(()=>{const form=document.getElementById('pickup-form'),picker=document.getElementById('photo-picker'),input=document.getElementById('photos'),box=document.getElementById('previews'),label=document.getElementById('label-index'),status=document.getElementById('ai-status'),video=document.getElementById('video'),camera=document.getElementById('camera');let files=[],stream=null;const key='pickup-draft-{{$preorder->id}}',other=document.getElementById('delivered-by-other'),otherFields=document.getElementById('other-signer'),signerName=document.getElementById('signer-name'),signerRut=document.getElementById('signer-rut');function toggleSigner(){otherFields.hidden=!other.checked;signerName.disabled=signerRut.disabled=!other.checked;signerName.required=signerRut.required=other.checked}other.addEventListener('change',toggleSigner);toggleSigner();function sync(){const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));input.files=dt.files;document.getElementById('photo-count').textContent=`${files.length} de 5`}function render(){box.innerHTML='';files.forEach((f,i)=>{const card=document.createElement('div');card.className='photo-card';const img=document.createElement('img');img.src=URL.createObjectURL(f);const l=document.createElement('label'),radio=document.createElement('input');radio.type='radio';radio.name='label-choice';radio.checked=label.value===String(i);radio.onchange=()=>label.value=i;l.append(radio,document.createTextNode('Etiqueta'));const b=document.createElement('button');b.type='button';b.className='btn danger';b.textContent='Eliminar';b.onclick=()=>{const old=Number(label.value);files.splice(i,1);if(old===i)label.value='';else if(old>i)label.value=old-1;sync();render()};card.append(img,l,b);box.append(card)})}function add(list){const room=5-files.length;files.push(...[...list].slice(0,room));if(list.length>room)alert('Máximo 5 fotografías.');picker.value='';sync();render()}picker.onchange=()=>add(picker.files);document.getElementById('start-camera').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1600}},audio:false});video.srcObject=stream;camera.hidden=false}catch(e){status.textContent='No fue posible abrir la cámara.'}};function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;camera.hidden=true}document.getElementById('stop-camera').onclick=stop;document.getElementById('capture').onclick=()=>{if(!stream||files.length>=5)return;const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);c.toBlob(blob=>blob&&add([new File([blob],`retiro-${Date.now()}.jpg`,{type:'image/jpeg'})]),'image/jpeg',.9)};
document.getElementById('analyze').onclick=async function(){const i=Number(label.value);if(label.value===''||!files[i]){status.textContent='Marca la foto de la etiqueta.';return}this.disabled=true;status.textContent='Analizando...';const data=new FormData();data.append('company_id','{{$preorder->company_id}}');data.append('image',files[i]);const recovery={{$preorder->service_area==='recuperadata'?'true':'false'}};try{const r=await fetch(recovery?'{{route('ai.analyze-storage-label')}}':'{{route('ai.analyze-device-label')}}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{csrf_token()}}','Accept':'application/json'},body:data}),d=await r.json();if(!r.ok||!d.success)throw new Error(d.message);const map={brand:'mobile-brand',model:'mobile-model',serial_number:'mobile-serial',capacity:'mobile-capacity',interface:'mobile-interface'};Object.entries(map).forEach(([k,id])=>{if(d.data[k]&&document.getElementById(id))document.getElementById(id).value=d.data[k]});status.textContent='Datos cargados; revísalos antes de finalizar.'}catch(e){status.textContent=e.message||'No fue posible analizar.'}finally{this.disabled=false}};
const canvas=document.getElementById('signature'),ctx=canvas.getContext('2d');ctx.lineWidth=4;ctx.lineCap='round';ctx.strokeStyle='#111827';let drawing=false,dirty=false;function point(e){const r=canvas.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:(p.clientX-r.left)*canvas.width/r.width,y:(p.clientY-r.top)*canvas.height/r.height}}function start(e){drawing=true;const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()}function move(e){if(!drawing)return;const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke();dirty=true;e.preventDefault()}function end(){drawing=false}['pointerdown'].forEach(n=>canvas.addEventListener(n,start));canvas.addEventListener('pointermove',move);window.addEventListener('pointerup',end);document.getElementById('clear-signature').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);dirty=false};form.addEventListener('input',()=>{const values={};form.querySelectorAll('input:not([type=file]):not([type=hidden]),textarea').forEach(f=>values[f.name]=f.value);localStorage.setItem(key,JSON.stringify(values))});try{const saved=JSON.parse(localStorage.getItem(key)||'{}');Object.entries(saved).forEach(([n,v])=>{const f=form.elements[n];if(f&&!f.value)f.value=v})}catch(e){}form.onsubmit=e=>{if(!files.length){e.preventDefault();alert('Debes adjuntar al menos una fotografía.');return}if(!dirty){e.preventDefault();alert('El cliente debe firmar antes de finalizar.');return}document.getElementById('signature-data').value=canvas.toDataURL('image/png');localStorage.removeItem(key);stop()};function connectivity(){const el=document.getElementById('connection-status');el.textContent=navigator.onLine?'':'Sin conexión: el borrador de texto queda guardado en este dispositivo.';el.classList.toggle('show',!navigator.onLine)}addEventListener('online',connectivity);addEventListener('offline',connectivity);connectivity();if('serviceWorker'in navigator)navigator.serviceWorker.register('{{asset('home-service-sw.js')}}');addEventListener('beforeunl